//! The built-in modifier markers: `variant::Filled`, `size::Md`,
//! `shape::Pill`, …
//!
//! Each component's variant, size and shape axes are its OWN types —
//! `ButtonVariant`, `BadgeVariant`, `ButtonSize` — generated by its
//! `component_styles!` declaration, so a value of one component's axis
//! never fits another's (a `card::variant::Flat` on a Button does not
//! compile, where a shared variant type compiled and drew nothing). The
//! markers here are the shared SPELLING: a marker converts into every
//! component axis that has that value, so `variant = variant::Ghost` reads
//! the same on a Button, a Badge or a Chip, and only where it means
//! something.
//!
//! The variant markers are also tone-aware surface recipes
//! ([`Variant`](idea_theme::extensible::Variant)): a component's `extend`
//! hook renders each over every registered tone, and an app gives one of
//! its own variant values the same tone-aware look with
//! [`tone_variant_arms`](idea_theme::extensible::tone_variant_arms).

/// `impl From<marker> for Axis` and `for Reactive<Axis>` (the `ui!`
/// call-site coercion) for each listed `marker => Axis::Value`.
macro_rules! marker_into_axis {
    ($axis:ty { $($marker:path => $value:ident),* $(,)? }) => { $(
        impl ::core::convert::From<$marker> for $axis {
            fn from(_: $marker) -> Self {
                <$axis>::$value
            }
        }
        impl ::core::convert::From<$marker> for ::runtime_core::Reactive<$axis> {
            fn from(m: $marker) -> Self {
                ::runtime_core::Reactive::Static(<$axis as ::core::convert::From<$marker>>::from(m))
            }
        }
    )* };
}
pub(crate) use marker_into_axis;

/// Tone-aware surface treatments.
///
/// | Variant | Background | Border | Text |
/// |---|---|---|---|
/// | [`Filled`]  | tone's `fill_bg` | none (width=0) | tone's `fill_fg` |
/// | [`Soft`]    | tone's `soft_bg` | none (width=0) | tone's `soft_fg` |
/// | [`Outlined`]| transparent | tone's `stroke_color` (1px) | tone's `stroke_fg` |
/// | [`Ghost`]   | transparent | none (width=0) | tone's `ghost_fg` |
/// | [`Gradient`]| the theme's accent gradient | none | `gradient_text` |
///
/// Variants set only the surface slots — background, text, border.
/// Padding, font size and radius come from the component's size and shape
/// axes. Border widths are set explicitly (0 where there is none) so every
/// arm fully specifies the border: a live switch from Outlined to Filled
/// must clear the stroke, and a native backend leaves an unset property as
/// it was.
pub mod variant {
    use idea_theme::extensible::variant::{no_border, GRADIENT_ANGLE_DEG};
    use idea_theme::extensible::{ResolutionCtx, Variant};
    use runtime_core::{Color, IdealystSchema, StyleRules, Tokenized};

    /// Filled — solid background, contrasting text.
    #[derive(Copy, Clone, Default, Debug, IdealystSchema)]
    #[schema(value_of = "ButtonVariant", via = "idea_ui::variant")]
    pub struct Filled;

    impl Variant for Filled {
        fn key(&self) -> &'static str {
            "filled"
        }
        fn render(&self, ctx: &ResolutionCtx) -> StyleRules {
            let mut s = no_border();
            s.background = Some(ctx.tone.fill_bg(ctx.theme));
            s.color = Some(ctx.tone.fill_fg(ctx.theme));
            s
        }
    }

    /// `Solid` — an alias for [`Filled`] ("solid" is the instinctive name
    /// for a solid-background button). A `const`, so `variant::Solid` works
    /// in value position; it IS a `Filled`.
    #[allow(non_upper_case_globals)]
    pub const Solid: Filled = Filled;

    /// Soft — tinted background, intent-colored text.
    #[derive(Copy, Clone, Default, Debug, IdealystSchema)]
    #[schema(value_of = "ButtonVariant", via = "idea_ui::variant")]
    pub struct Soft;

    impl Variant for Soft {
        fn key(&self) -> &'static str {
            "soft"
        }
        fn render(&self, ctx: &ResolutionCtx) -> StyleRules {
            let mut s = no_border();
            s.background = Some(ctx.tone.soft_bg(ctx.theme));
            s.color = Some(ctx.tone.soft_fg(ctx.theme));
            s
        }
    }

    /// Outlined — transparent fill, intent-colored 1px border + text.
    #[derive(Copy, Clone, Default, Debug, IdealystSchema)]
    #[schema(value_of = "ButtonVariant", via = "idea_ui::variant")]
    pub struct Outlined;

    impl Variant for Outlined {
        fn key(&self) -> &'static str {
            "outlined"
        }
        fn render(&self, ctx: &ResolutionCtx) -> StyleRules {
            let stroke = ctx.tone.stroke_color(ctx.theme);
            let one_px = Tokenized::Literal(1.0);
            StyleRules {
                background: Some(Tokenized::Literal(Color("transparent".into()))),
                color: Some(ctx.tone.stroke_fg(ctx.theme)),
                border_top_width: Some(one_px.clone()),
                border_right_width: Some(one_px.clone()),
                border_bottom_width: Some(one_px.clone()),
                border_left_width: Some(one_px),
                border_top_color: Some(stroke.clone()),
                border_right_color: Some(stroke.clone()),
                border_bottom_color: Some(stroke.clone()),
                border_left_color: Some(stroke),
                ..Default::default()
            }
        }
    }

    /// Ghost — transparent fill, no border, intent-colored text only.
    #[derive(Copy, Clone, Default, Debug, IdealystSchema)]
    #[schema(value_of = "ButtonVariant", via = "idea_ui::variant")]
    pub struct Ghost;

    impl Variant for Ghost {
        fn key(&self) -> &'static str {
            "ghost"
        }
        fn render(&self, ctx: &ResolutionCtx) -> StyleRules {
            let mut s = no_border();
            s.background = Some(Tokenized::Literal(Color("transparent".into())));
            s.color = Some(ctx.tone.ghost_fg(ctx.theme));
            s
        }
    }

    /// Gradient — the theme's accent gradient (`Effects::gradient_*`) as
    /// the fill, its `gradient_text` on top. Tone-independent in color, but
    /// a semantic tone still picks the hover glow.
    ///
    /// Opt-in: every built-in variant multiplies the build-time CSS of
    /// every tone of every component that draws it, so no component
    /// renders it until the app asks — a restyle at boot:
    ///
    /// ```ignore
    /// ButtonStyles::restyle(|s| {
    ///     tone_variant_arms(&mut s.root(), &semantic_tones(), "gradient", &variant::Gradient);
    ///     tone_variant_arms(&mut s.label(), &semantic_tones(), "gradient", &variant::Gradient);
    /// });
    /// ```
    #[derive(Copy, Clone, Default, Debug, IdealystSchema)]
    #[schema(value_of = "ButtonVariant", via = "idea_ui::variant")]
    pub struct Gradient;

    impl Variant for Gradient {
        fn key(&self) -> &'static str {
            "gradient"
        }
        fn render(&self, ctx: &ResolutionCtx) -> StyleRules {
            let e = ctx.theme.effects();
            let mut s = no_border();
            // Solid fallback under the gradient: what shows if a backend
            // can't paint it, and what text contrast is checked against.
            s.background = Some(e.gradient_start.clone());
            s.background_gradient = Some(runtime_core::Gradient {
                kind: runtime_core::GradientKind::Linear { angle_deg: GRADIENT_ANGLE_DEG },
                stops: vec![
                    runtime_core::GradientStop { offset: 0.0, color: e.gradient_start.clone() },
                    runtime_core::GradientStop { offset: 0.5, color: e.gradient_mid.clone() },
                    runtime_core::GradientStop { offset: 1.0, color: e.gradient_end.clone() },
                ],
            });
            s.color = Some(e.gradient_text.clone());
            s
        }
    }

    /// The four built-in variant recipes a tone-aware component renders by
    /// default, by key.
    pub fn builtin_recipes() -> [(&'static str, &'static dyn Variant); 4] {
        [("filled", &Filled), ("soft", &Soft), ("outlined", &Outlined), ("ghost", &Ghost)]
    }

    // A component not yet on its own variant axis still takes a shared
    // `VariantRef`; the markers coerce into it in a `ui!` call site.
    macro_rules! variant_ref_coercion {
        ($($name:ident),*) => { $(
            impl ::core::convert::From<$name> for ::runtime_core::Reactive<idea_theme::extensible::VariantRef> {
                fn from(marker: $name) -> Self {
                    ::runtime_core::Reactive::Static(idea_theme::extensible::VariantRef::from(marker))
                }
            }
        )* };
    }
    variant_ref_coercion!(Filled, Soft, Outlined, Ghost, Gradient);
}

/// Button padding / font scale markers.
pub mod size {
    use runtime_core::IdealystSchema;

    /// Small.
    #[derive(Copy, Clone, Default, Debug, IdealystSchema)]
    #[schema(value_of = "ButtonSize", via = "idea_ui::size")]
    pub struct Sm;
    /// Medium (the default).
    #[derive(Copy, Clone, Default, Debug, IdealystSchema)]
    #[schema(value_of = "ButtonSize", via = "idea_ui::size")]
    pub struct Md;
    /// Large.
    #[derive(Copy, Clone, Default, Debug, IdealystSchema)]
    #[schema(value_of = "ButtonSize", via = "idea_ui::size")]
    pub struct Lg;
}

/// Corner-radius markers.
pub mod shape {
    use runtime_core::IdealystSchema;

    /// The theme's small radius.
    #[derive(Copy, Clone, Default, Debug, IdealystSchema)]
    #[schema(value_of = "ButtonShape", via = "idea_ui::shape")]
    pub struct Sm;
    /// The theme's medium radius (the default).
    #[derive(Copy, Clone, Default, Debug, IdealystSchema)]
    #[schema(value_of = "ButtonShape", via = "idea_ui::shape")]
    pub struct Md;
    /// The theme's large radius.
    #[derive(Copy, Clone, Default, Debug, IdealystSchema)]
    #[schema(value_of = "ButtonShape", via = "idea_ui::shape")]
    pub struct Lg;
    /// Fully rounded ends.
    #[derive(Copy, Clone, Default, Debug, IdealystSchema)]
    #[schema(value_of = "ButtonShape", via = "idea_ui::shape")]
    pub struct Pill;
}
